pub fn visit_terminator_fields<W: Words + ?Sized>(kind: TerminatorKind, words: &W, at: usize, visit: &mut dyn FnMut(FieldWord, usize)) -> Option<usize> {
    let mut at = at;
    match kind {
        TerminatorKind::Jump | TerminatorKind::Unreachable => {}
        TerminatorKind::Branch | TerminatorKind::Throw | TerminatorKind::Rethrow => {
            present(words, &mut at, FieldWord::Operand, visit)?;
        }
        TerminatorKind::Switch => {
            present(words, &mut at, FieldWord::Operand, visit)?;
            counted_words(words, &mut at, 2)?;
        }
        TerminatorKind::SwitchString => {
            present(words, &mut at, FieldWord::Operand, visit)?;
            counted(words, &mut at, FieldWord::Reference(ReferenceKind::String), visit)?;
        }
        TerminatorKind::Return => {
            optional(words, &mut at, FieldWord::Operand, visit)?;
        }
        TerminatorKind::ReturnCall => {
            present(words, &mut at, FieldWord::Operand, visit)?;
            counted_records(words, &mut at, visit, TailCast::visit_words)?;
        }
    }
    Some(at)
}

#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub enum OperandWord {
    // The index of the operand in the operation's own list of operands.
    Operand(u32),
    Key,
}

type VisitOperand<'v> = &'v mut dyn FnMut(OperandWord, usize);

fn operand<W: Words + ?Sized>(words: &W, at: &mut usize, index: u32, visit: VisitOperand<'_>) -> Option<()> {
    if words.get(*at)? != ABSENT_WORD {
        visit(OperandWord::Operand(index), *at);
    }
    *at += 1;
    Some(())
}

fn operands<W: Words + ?Sized>(words: &W, at: &mut usize, first_index: u32, visit: VisitOperand<'_>) -> Option<()> {
    let count = words.get(*at)?;
    *at += 1;
    for ordinal in 0..count {
        words.get(*at)?;
        visit(OperandWord::Operand(first_index + ordinal), *at);
        *at += 1;
    }
    Some(())
}

fn key<W: Words + ?Sized>(words: &W, at: &mut usize, visit: VisitOperand<'_>) -> Option<()> {
    if words.get(*at)? != ABSENT_WORD {
        visit(OperandWord::Key, *at);
    }
    *at += 1;
    Some(())
}

